function generateRandomPassword(length, includeSpecialChars = false) {
  const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789" + (includeSpecialChars ? "!@#$%^&*()_+-=[]{};:,.<>?\\|/~" : "");
  let password = "";
  let hasUppercase = false;
  let hasLowercase = false;
  let hasNumber = false;

  // Ensure password meets minimum length
  if (length < 8) {
    throw new Error("Password length must be at least 8 characters")
  }

  // Generate a random character for each position in the password
  for (let I = 0; I < length; i++) {
    const randomIndex = Math.floor(Math.random() * charset.length);
    const randomChar = charset[randomIndex];
    password += randomChar;

    // Keep track of whether the password contains uppercase letters, lowercase letters, and numbers
    if (/[A-Z]/.test(randomChar)) {
      hasUppercase = true;
    } else if (/[a-z]/.test(randomChar)) {
      hasLowercase = true;
    } else if (/\d/.test(randomChar)) {
      hasNumber = true;
    }
  }

  // If the password doesn't meet the criteria, generate a new one
  if (!hasUppercase || !hasLowercase || !hasNumber) {
    return generateRandomPassword(length, includeSpecialChars);
  }

  return password;
}
```

