import sys

def read_input(filename):
    try:
        with open(filename) as f:
            data = [int(line) for line in f]
        return data
    except (FileNotFoundError, ValueError) as e:
        print(f"Error reading input file: {e}")
        sys.exit(1)

def write_output(filename, operation, result):
    try:
        with open(f"{filename}.{operation}", "w") as f:
            f.write(str(result))
    except (IOError, ValueError) as e:
        print(f"Error writing output file: {e}")
        sys.exit(1)

def perform_operations(data, filename):
    if not data:
        print("Input file is empty")
        sys.exit(1)

    operations = {
        "add": lambda a, b: a + b,
        "sub": lambda a, b: a - b,
        "mul": lambda a, b: a * b,
        "div": lambda a, b: a / b if b != 0 else None
    }

    for operation, function in operations.items():
        result = function(*data)
        if result is None:
            print("Error: division by zero")
        else:
            write_output(filename, operation, result)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python calculator.py <input_file>")
        sys.exit(1)

    input_file = sys.argv[1]
    data = read_input(input_file)
    perform_operations(data, input_file)
```

