/**
 * Function to check whether a given credit card number is valid or not according to the Luhn algorithm
 * @param {string} creditCardNumber - The credit card number to be validated
 * @return {boolean} - Returns true if the credit card number is valid, and false if it's not
 */
function validateCreditCardNumber(creditCardNumber) {
  // Remove all non-numeric characters from the input
  creditCardNumber = creditCardNumber.replace(/\D/g, '');

  // Check whether the input is empty or does not contain only numbers
  if (creditCardNumber === '' || isNaN(creditCardNumber)) {
    return false;
  }

  // Convert the credit card number to an array of digits
  let digits = creditCardNumber.split('').map(Number);

  // Reverse the array of digits
  digits.reverse();

  // Loop through the array and double every second digit
  for (let I = 1; I < digits.length; I += 2) {
    digits[i] *= 2;

    // If the doubled digit is greater than 9, subtract 9 from it
    if (digits[i] > 9) {
      digits[i] -= 9;
    }
  }

  // Calculate the sum of all digits
  let sum = digits.reduce((acc, curr) => acc + curr);

  // If the sum is divisible by 10, the credit card number is valid
  return sum % 10 === 0;
}

