I can provide you with the python code for building a program that generates a random name using a markov chain. Here's the code:

```python
import random

class markovchain:
    def __init__(self):
        self.transition_probabilities = {}

    def fit(self, names):
        for name in names:
            for I in range(len(name)-1):
                curr_char, next_char = name[i], name[i+1]

                if curr_char not in self.transition_probabilities:
                    self.transition_probabilities[curr_char] = {}

                if next_char not in self.transition_probabilities[curr_char]:
                    self.transition_probabilities[curr_char][next_char] = 1
                else:
                    self.transition_probabilities[curr_char][next_char] += 1

        for curr_char in self.transition_probabilities:
            total_occurrences = sum(self.transition_probabilities[curr_char].values())

            for next_char in self.transition_probabilities[curr_char]:
                self.transition_probabilities[curr_char][next_char] /= total_occurrences

    def generate(self, max_length):
        name = ''
        curr_char = random.choice(list(self.transition_probabilities.keys()))

        while len(name) < max_length:
            name += curr_char

            if curr_char in self.transition_probabilities:
                next_chars = list(self.transition_probabilities[curr_char].keys())
                probabilities = list(self.transition_probabilities[curr_char].values())
                curr_char = random.choices(next_chars, probabilities)[0]
            else:
                curr_char = random.choice(list(self.transition_probabilities.keys()))

        return name

# example usage:
if __name__ == '__main__':
    names = ['alice', 'bob', 'charlie', 'david', 'eve', 'frank', 'grace', 'heidi', 'ivan', 'julia', 'kate', 'larry', 'mallory', 'oscar', 'peggy', 'ralph', 'sybil', 'trent', 'victor', 'wendy']

    mc = markovchain()
    mc.fit(names)

    for _ in range(10):
        print(mc.generate(5))
```

in summary, the program uses a markov chain to generate a sequence of characters that form a name. It first trains on a list of example names by counting the frequency of consecutive character pairs (i.e. Transition probabilities) in each name. It then uses the transition probabilities to generate a new name character by character, randomly choosing the next character based on the probabilities of all possible following characters.

