# define a tree node
struct node {
    int data
    node *left
    node *right
}

# initialize an empty tree
set root {}

# function to insert a value into the binary search tree
proc insert {treenode value} {
    # create a new tree node with the given value
    set newnode [struct node -data $value -left {} -right {}]

    # if the tree is empty, make the new node the root
    if {$treenode eq {}} {
        set treenode $newnode
        return
    }

    # insert the new node in the appropriate position
    if {$value < $treenode.data} {
        insert $treenode.left $value
    } else {
        insert $treenode.right $value
    }
}

# function to search for a value in the binary search tree
proc search {treenode value} {
    # if the tree is empty, the value is not found
    if {$treenode eq {}} {
        return 0
    }

    # if the current node's value is the target value, return true
    if {$value == $treenode.data} {
        return 1
    }

    # if the target value is less than the current node's value, search the left subtree
    if {$value < $treenode.data} {
        return [search $treenode.left $value]
    }

    # if the target value is greater than the current node's value, search the right subtree
    return [search $treenode.right $value]
}

# function to find the minimum value in the binary search tree
proc findmin {treenode} {
    # if the left subtree is empty, the current node is the minimum
    if {$treenode.left eq {}} {
        return $treenode.data
    }

    # recursively search the left subtree
    return [findmin $treenode.left]
}

# function to delete a value from the binary search tree
proc delete {treenode value} {
    # if the tree is empty, the value is not found
    if {$treenode eq {}} {
        return $treenode
    }

    # if the target value is less than the current node's value, delete from the left subtree
    if {$value < $treenode.data} {
        set treenode.left [delete $treenode.left $value]
        return $treenode
    }

    # if the target value is greater than the current node's value, delete from the right subtree
    if {$value > $treenode.data} {
        set treenode.right [delete $treenode.right $value]
        return $treenode
    }

    # if the current node has no child or only one child, simply remove it
    if {$treenode.left eq {}} {
        set temp $treenode.right
        unset $treenode
        return $temp
    } elseif {$treenode.right eq {}} {
        set temp $treenode.left
        unset $treenode
        return $temp
    }

    # if the current node has two children, find the minimum value in the right subtree
    set minvalue [findmin $treenode.right]

    # set the current node's value to the minimum value
    set treenode.data $minvalue

    # delete the minimum value from the right subtree
    set treenode.right [delete $treenode.right $minvalue]

    return $treenode
} 

