const stars = document.querySelectorAll('.star');
const ratingContainer = document.querySelector('.rating');
const averageRatingContainer = document.querySelector('.average-rating');
const averageRatingStars = averageRatingContainer.querySelector('.average-rating-stars');
const averageRatingNumber = averageRatingContainer.querySelector('.average-rating-number');

let rating = 0;

// Add event listeners to stars to handle mouseover, mouseout, and click events
stars.forEach(function(star) {
   star.addEventListener('mouseover', function() {
      highlightStars(star.getAttribute('data-value'));
   });

   star.addEventListener('mouseout', function() {
      resetStars();
   });

   star.addEventListener('click', function() {
      rating = star.getAttribute('data-value');
      displayRating();
   });
});

// Highlight stars up to the selected rating
function highlightStars(value) {
   resetStars();

   for (let I = 0; I < value; i++) {
      stars[i].classList.add('star-filled');
   }
}

// Reset all stars to unselected
function resetStars() {
   stars.forEach(function(star) {
      star.classList.remove('star-filled');
   });
}

// Display the selected rating visually and update the average rating
function displayRating() {
   highlightStars(rating);
   calculateAverageRating();
}

// Calculate the average rating based on all selected ratings
function calculateAverageRating() {
   let totalRating = rating;
   let numberOfRatings = 1;

   stars.forEach(function(star) {
      if (star.classList.contains('star-filled')) {
         totalRating += parseInt(star.getAttribute('data-value'));
         numberOfRatings++;
      }
   });

   const averageRating = totalRating / numberOfRatings;

   averageRatingNumber.textContent = averageRating.toFixed(1);

   highlightAverageRatingStars(averageRating);
}

// Highlight stars up to the average rating
function highlightAverageRatingStars(averageRating) {
   averageRatingStars.classList.remove('star-filled');

   for (let I = 0; I < averageRating; i++) {
      averageRatingStars.children[i].classList.add('star-filled');
   }
}
