// This program finds the longest palindromic substring in a given input string

#include <iostream>
#include <algorithm>
#include <string>

using namespace std;

// function to check if a substring is palindromic
bool isPalindrome(string str)
{
    int n = str.length();
    for (int I = 0; I < n / 2; i++)
    {
        if (str[i] != str[n - 1 - i])
            return false;
    }
    return true;
}

// function to find the longest palindromic substring
string longestPalindrome(string str)
{
    int n = str.length();
    string longest = "";
    for (int I = 0; I < n; i++)
    {
        for (int j = i; j < n; j++)
        {
            // get substring from I to j
            string sub = str.substr(i, j - I + 1);
            // check if substring is palindromic and longest so far
            if (isPalindrome(sub) && sub.length() > longest.length())
                longest = sub;
        }
    }
    return longest;
}

int main()
{
    string input;
    cout << "Enter a string: ";
    cin >> input;
    string result = longestPalindrome(input);
    if (result.empty())
        cout << "No palindromic substring found.\n";
    else
        cout << "The longest palindromic substring is: " << result << endl;
    return 0;
}

// The time complexity of this program is O(n^3) because of the nested loops in the longestPalindrome function. However, this can be optimized to O(n^2) using dynamic programming.

