% Check if matrix is invertible (i.e. Determinant is non-zero)
if det_matrix == 0
    error('Matrix is non-invertible');
end

% Calculate adjugate matrix
adj_matrix = adjoint(matrix);

% Calculate inverse of the matrix using det and adjugate matrix
inv_matrix = adj_matrix / det_matrix;

% Display the original matrix along with its determinant and inverse
fprintf('Original Matrix:\n');
disp(matrix);

fprintf('Determinant: %f\n', det_matrix);

fprintf('Inverse:\n');
try
    disp(inv_matrix);
    fprintf('Successfully computed inverse.\n');
catch
    fprintf('Error computing inverse.\n');
end

% Adjoint function calculates the adjugate matrix of square matrix A
function adj = adjoint(A)
    n = size(A,1);
    adj = zeros(n,n);
    for I = 1:n
        for j = 1:n
            B = A;
            B(i,:) = [];
            B(:,j) = [];
            adj(j,i) = (-1)^(i+j) * det(B);
        end
    end
end

