Here is a C# program that implements the Longest Common Subsequence algorithm using dynamic programming:

```
using System;

class LCS
{
    static void Main()
    {
        Console.WriteLine("Enter first string: ");
        string str1 = Console.ReadLine();

        Console.WriteLine("Enter second string: ");
        string str2 = Console.ReadLine();

        int len = LongestCommonSubsequence(str1, str2);

        Console.WriteLine($"Length of Longest Common Subsequence: {len}");
    }

    static int LongestCommonSubsequence(string str1, string str2)
    {
        int m = str1.Length;
        int n = str2.Length;

        if (m == 0 || n == 0) // check if either string is empty
            return 0;

        int[,] L = new int[m + 1, n + 1];

        // Build the L[m+1][n+1] table in a bottom-up manner
        for (int I = 0; I <= m; i++)
        {
            for (int j = 0; j <= n; j++)
            {
                if (i == 0 || j == 0)
                    L[i, j] = 0; // initialize first row and column to zero
                else if (str1[i - 1] == str2[j - 1])
                    L[i, j] = L[i - 1, j - 1] + 1; // if the characters match, add to previous length
                else
                    L[i, j] = Math.Max(L[i - 1, j], L[i, j - 1]); // otherwise, take the max of two previous lengths
            }
        }

        return L[m, n];
    }
}
```

