public static int CountWordsWithRepeatedLetters(string input)
{
    // Edge case: empty string or null
    if (string.IsNullOrEmpty(input))
        return 0;

    int count = 0;

    // Split the input into words
    string[] words = input.Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);

    foreach (string word in words)
    {
        bool repeated = false;

        // Convert the word to lowercase for case-insensitive comparison
        string lower = word.ToLower();

        // Check if the word has consecutive repeated letters
        for (int I = 0; I < lower.Length - 1; i++)
        {
            if (lower[i] == lower[i + 1])
            {
                repeated = true;
                break; // no need to check the rest of the word
            }
        }

        if (repeated)
            count++;
    }

    return count;
}
