use std::collections::{BinaryHeap, HashMap};

#[derive(Debug)]
struct Graph {
    adjacency_list: HashMap<usize, Vec<(usize, u32)>>,
}

impl Graph {
    fn new(num_vertices: usize) -> Self {
        let adjacency_list = HashMap::with_capacity(num_vertices);
        Self { adjacency_list }
    }

    fn add_edge(&mut self, start: usize, end: usize, weight: u32) {
        let entry = self.adjacency_list.entry(start).or_insert(Vec::new());
        entry.push((end, weight));
    }

    fn dijkstra_shortest_path(&self, start: usize, end: usize) -> Option<(u32, Vec<usize>)> {
        let mut heap: BinaryHeap<(u32, usize, Vec<usize>)> = BinaryHeap::new();
        heap.push((0, start, vec![start]));
        let mut visited: HashMap<usize, u32> = HashMap::new();
        visited.insert(start, 0);

        while let Some((cost, node, path)) = heap.pop() {
            if node == end {
                return Some((cost, path));
            }
            if let Some(adjacent) = self.adjacency_list.get(&node) {
                for (neighbor, weight) in adjacent {
                    let new_cost = cost + weight;
                    if !visited.contains_key(&neighbor) || visited[neighbor] > new_cost {
                        visited.insert(*neighbor, new_cost);
                        let mut new_path = path.clone();
                        new_path.push(*neighbor);
                        heap.push((new_cost, *neighbor, new_path));
                    }
                }
            }
        }
        None
    }
}

fn main() {
