// Define a function to find the greatest common divisor using the Euclidean algorithm.
fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

// Define the main function that prompts the user and calculates the greatest common divisor.
fn main() {
    // Print the prompt to the console.
    print!("Please enter two non-negative integers separated by a space: ");

    // Flush the console input to ensure everything is printed.
    io::stdout().flush().unwrap();

    // Create a variable to store the user input.
    let mut input = String::new();

    // Read the user input from the console.
    io::stdin().read_line(&mut input).unwrap();

    // Parse the user input into two unsigned 32-bit integers.
    let mut nums = match input.trim().split_whitespace().map(|x| x.parse::<u32>()).collect::<Result<Vec<u32>, _>>() {
        Ok(nums) if nums.len() == 2 => nums,
        _ => {
            // Print an error message if the user input is invalid.
            eprintln!("Please enter two non-negative integers separated by a space.");
            return;
        }
    };

    // Check that the two numbers are non-negative.
    if nums[0] == 0 || nums[1] == 0 {
        // Print an error message if either number is zero.
        eprintln!("Please enter two non-negative integers separated by a space.");
        return;
    }

    // If the first number is smaller than the second, swap them.
    if nums[0] < nums[1] {
        nums.swap(0, 1);
    }

    // Calculate the greatest common divisor and print it to the console.
    let result = gcd(nums[0], nums[1]);
    println!("The greatest common divisor is: {}", result);
}

