        self._search_helper(letters.lower(), self.root, "", words, min_length)
        return words

    def find_max_score(self, letters, min_length=3):
        max_score = 0
        max_word = None
        self._max_score_helper(letters.lower(), self.root, "", max_score, max_word, min_length)
        return (max_score, max_word)

