```
#include <stdio.h>

void bubble_sort(int arr[], int n) {
    int i, j, temp;
    for (i = 0; I < n - 1; i++) {
        // iterate through the array up to n-1 elements
        for (j = 0; j < n - I - 1; j++) {
            // iterate through the unsorted portion of the array
            if (arr[j] > arr[j + 1]) {
                // swap adjacent elements if they are in the wrong order
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

