use rand::rng;
use std::collections::hashset;

#[derive(clone, copy, debug, partialeq)]
pub enum cell {
    start,
    end,
    wall,
    path,
}

const neighbors: [(isize, isize); 4] = [(-1, 0), (0, 1), (1, 0), (0, -1)];

pub struct maze {
    w: usize,
    h: usize,
    start: (usize, usize),
    end: (usize, usize),
    cells: vec<vec<cell>>,
}

impl maze {
    pub fn new(w: usize, h: usize) -> self {
        let mut cells = vec![vec![cell::wall; h]; w];
        let start = (0, 0);
        let end = (w - 1, h - 1);
        cells[start.0][start.1] = cell::start;
        cells[end.0][end.1] = cell::end;

        self { w, h, start, end, cells }
    }

    pub fn generate(&mut self) {
        let mut visited = hashset::new();
        visited.insert((self.start.0, self.start.1));

        self.dfs((self.start.0, self.start.1), &mut visited);
    }

    fn dfs(&mut self, current: (usize, usize), visited: &mut hashset<(usize, usize)>) {
        for neighbor in self.neighbors(current) {
            if !visited.contains(&neighbor) {
                visited.insert(neighbor);
                self.cells[neighbor.0][neighbor.1] = cell::path;
                self.dfs(neighbor, visited);
            }
        }
    }

    fn neighbors(&self, current: (usize, usize)) -> vec<(usize, usize)> {
        let mut neighbors = vec![];
        for (dx, dy) in neighbors.iter() {
            let x = current.0 as isize + dx;
            let y = current.1 as isize + dy;
            if x >= 0 && x < self.w as isize && y >= 0 && y < self.h as isize {
                let x = x as usize;
                let y = y as usize;
                neighbors.push((x, y));
            }
        }
        neighbors
    }
}

fn main() {
    let w = 10;
    let h = 10;

    let mut maze = maze::new(w, h);
    maze.generate();

    for row in 0..h {
        for col in 0..w {
            match maze.cells[col][row] {
                cell::wall => print!("#"),
                cell::start => print!("s"),
                cell::end => print!("e"),
                cell::path => print!("."),
            }
        }
        println!();
    }
}
