/* 
This program implements the insertion sort technique to sort an array of integers in ascending order.
Author: [Your Name]
Date: [Date]

Steps for insertion sort:
1. Start from the second element in the array i.e. Index 1 to n-1
2. Compare the current element with the largest element on the left
3. If the current element is smaller than the largest element on the left, then swap them
4. Repeat step 2 and 3 until the current element is in its correct position in the array
5. Repeat steps 1 to 4 until the entire array is sorted

*/

public class InsertionSort {

  public static void insertionSort(int[] arr) {

    for (int I = 1; I < arr.length; i++) {

      int currentElement = arr[i]; // save the current element
      int j = I - 1; // start comparing with the previous element

      while (j >= 0 && arr[j] > currentElement) {
        arr[j + 1] = arr[j]; // move the larger element to the right
        j--; // compare with the previous element
      }
      arr[j + 1] = currentElement; // insert the current element in its correct position
    }
  }

  public static void main(String[] args) {

    int[] arr = {5, 2, 8, 3, 1}; // input array

    System.out.println("Original Array: "+ Arrays.toString(arr)); // prints the original array

    insertionSort(arr); // call the insertionSort method

    System.out.println("Sorted Array: "+ Arrays.toString(arr)); // prints the sorted array
  }
}

