		fmt.Println(err)
		return
	}
	defer outputFile.Close()

	// Create buffer for reading and writing chunks of data
	bufferSize := 1024 * 1024 // 1MB
	buffer := make([]byte, bufferSize)

	// Loop over input file, reading and writing data in chunks
	for {
		bytesRead, err := inputFile.Read(buffer)
		if err == io.EOF {
			// End of file reached, break out of loop
			break
		} else if err != nil {
			fmt.Println(err)
			return
		}

		_, err = outputFile.Write(buffer[:bytesRead])
		if err != nil {
			fmt.Println(err)
			return
		}
	}

	fmt.Println("Data copied successfully!")
}
```

This script uses a buffer of size `1024 * 1024` bytes (1MB) to read and write data in chunks. It reads data from the input file in chunks using `inputFile.Read()` and writes it to the output file using `outputFile.Write()`. The loop continues until the end of file is reached (`io.EOF`) or an error occurs. This approach should be more efficient for large files because it avoids reading and writing the entire file into memory at once.

