```
public class dtw {

    public static double dtwdistance(double[] seq1, double[] seq2) {
        int n = seq1.length;
        int m = seq2.length;
        double[][] dtw = new double[n + 1][m + 1];

        for (int I = 0; I <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dtw[i][j] = double.positive_infinity;
            }
        }

        dtw[0][0] = 0;

        for (int I = 1; I <= n; i++) {
            for (int j = 1; j <= m; j++) {
                double cost = math.abs(seq1[i - 1] - seq2[j - 1]);
                dtw[i][j] = cost + math.min(dtw[i - 1][j], math.min(dtw[i][j - 1], dtw[i - 1][j - 1]));
            }
        }

        return dtw[n][m];
    }

}
```

