Here's a Java program that generates a maze using the depth-first search algorithm:

import java.util.Random;

public class MazeGenerator {

    private int width;
    private int height;
    private int[][] maze;
    private Random random;

    public MazeGenerator(int width, int height) {
        this.width = width;
        this.height = height;
        this.maze = new int[width][height];
        this.random = new Random();
    }

    public void generateMaze() {
        // initialize maze with walls
        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                maze[x][y] = 1;
            }
        }

        // create path through maze using depth-first search
        int startX = random.nextInt(width);
        int startY = random.nextInt(height);
        dfs(startX, startY);
    }

    private void dfs(int x, int y) {
        maze[x][y] = 0;

        int[][] directions = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
        shuffle(directions);

        for (int[] dir : directions) {
            int newX = x + dir[0];
            int newY = y + dir[1];
            if (newX >= 0 && newX < width && newY >= 0 && newY < height && maze[newX][newY] == 1) {
                maze[x + dir[0] / 2][y + dir[1] / 2] = 0;
                dfs(newX, newY);
            }
        }
    }

    private void shuffle(int[][] array) {
        for (int I = 0; I < array.length; i++) {
            int[] temp = array[i];
            int randomIndex = random.nextInt(array.length);
            array[i] = array[randomIndex];
            array[randomIndex] = temp;
        }
    }

