// Function to generate Fibonacci sequence using recursion
List<int> fibonacciSequence(int n) {
  if (n == 1) {
    return [0];
  } else if (n == 2) {
    return [0, 1];
  } else {
    List<int> seq = fibonacciSequence(n - 1);
    int nextNum = seq[seq.length - 1] + seq[seq.length - 2];
    seq.add(nextNum);
    return seq;
  }
}

void main() {
  // Ask user for input
  stdout.write('Enter a number: ');
