Here's an implementation of a stack that can evaluate postfix expressions in C++:

```
#include <iostream>
#include <stack>
#include <sstream>

using namespace std;

class PostfixEvaluator {
public:
    int evaluate(string str) {
        stack<int> s;
        stringstream ss(str);
        string token;
        while (getline(ss, token, ' ')) {
            if (isOperator(token)) {
                int b = s.top();
                s.pop();
                int a = s.top();
                s.pop();
                int res = applyOperator(token[0], a, b);
                s.push(res);
            } else {
                int num = stoi(token);
                s.push(num);
            }
        }
        if (s.size() == 1) {
            return s.top();
        } else {
            throw "Invalid expression";
        }
    }
private:
    bool isOperator(string str) {
        return str.size() == 1 && string("+-*/").find(str) != string::npos;
    }
    int applyOperator(char op, int a, int b) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '/':
                if (b == 0) throw "Division by zero";
                return a / b;
            default: throw "Unknown operator";
        }
    }
};

int main() {
    PostfixEvaluator evaluator;
    cout << "Enter a postfix expression: ";
    string input;
    getline(cin, input);
    try {
        int result = evaluator.evaluate(input);
        cout << "Result: " << result << endl;
    } catch (const char* err) {
        cout << "Error: " << err << endl;
    }
    return 0;
}
```

The `PostfixEvaluator` class has a single public method `evaluate` that takes in a string representing a postfix expression and returns its integer value. The class uses a `stack<int>` to keep track of operands and applies operators by popping two operands from the stack, applying the operator, and pushing the result back onto the stack.

The `main` function asks the user to input a postfix expression, passes it to the `PostfixEvaluator` instance, and displays the result or any error messages that may occur during evaluation.

