```typescript
interface LoanInput {
  amount: number;
  rate: number;
  duration: number;
}

export function calculateLoanInterest({ amount, rate, duration }: LoanInput): number {
  if (amount <= 0) {
    throw new Error("Loan amount must be greater than zero.");
  }
  if (rate <= 0) {
    throw new Error("Interest rate must be greater than zero.");
  }
  if (duration <= 0) {
    throw new Error("Loan duration must be greater than zero.");
  }

  const interestRate = rate / 100;
  const compoundedInterest = Math.pow(1 + interestRate, duration);
  const totalAmount = amount * compoundedInterest;
  return parseFloat(totalAmount.toFixed(2));
}
```

