```c
#include <stdio.h>
#include <stdlib.h>

#define STACK_MAX 100 // maximum size of stack

// struct definition for stack
typedef struct {
    int items[STACK_MAX]; // array of integers to store stack elements
    int top; // top element of stack
} stack;

// function to create a new stack
stack *new_stack() {
    stack *s = malloc(sizeof(stack)); // allocate memory for stack struct
    s->top = -1; // initialize top to -1 (empty stack)
    return s;
}

// function to push element to stack
void push(stack *s, int value) {
    if (s->top == STACK_MAX - 1) { // stack is full
        printf("Error: stack overflow\n");
        return;
    }
    s->top++; // increment top
    s->items[s->top] = value; // add value to top of stack
}

// function to pop element from stack
int pop(stack *s) {
    if (s->top == -1) { // stack is empty
        printf("Error: stack underflow\n");
        return -1;
    }
    int value = s->items[s->top]; // value of top element
    s->top--; // decrement top
    return value; // return value of top element
}

// function to peek at top element of stack
int peek(stack *s) {
    if (s->top == -1) { // stack is empty
        printf("Error: stack underflow\n");
        return -1;
    }
    return s->items[s->top]; // return value of top element
}

int main() {
    stack *s = new_stack(); // create a new stack
    push(s, 10); // add 10 to stack
    push(s, 20); // add 20 to stack
    push(s, 30); // add 30 to stack
    printf("Top element: %d\n", peek(s)); // should print 30
    printf("Pop: %d\n", pop(s)); // should print 30
    printf("Top element: %d\n", peek(s)); // should print 20
    push(s, 40); // add 40 to stack
    printf("Top element: %d\n", peek(s)); // should print 40
    printf("Pop: %d\n", pop(s)); // should print 40
    printf("Pop: %d\n", pop(s)); // should print 20
    printf("Pop: %d\n", pop(s)); // should print 10
    printf("Top element: %d\n", peek(s)); // should print error message
    return 0;
}
```

Here's an optimized and well-commented C++ function that takes in two integers and outputs their greatest common divisor using the Euclidean algorithm:

```c++
#include <iostream>
#include <cmath>

using namespace std;

/* Function to calculate GCD of two numbers using Euclidean algorithm */
int gcd(int num1, int num2) {
    // Check if both numbers are zero
    if (num1 == 0 && num2 == 0) {
        return 0;
    }

    // Check if one number is zero
    if (num1 == 0 || num2 == 0) {
        return abs(num1 + num2); // Return absolute value of sum
    }

    // Ensure num1 is greater than or equal to num2
    if (abs(num1) < abs(num2)) {
        swap(num1, num2); // Swap values
    }

    // Use the Euclidean algorithm to find the GCD
    int remainder;
    while (num2 != 0) {
        remainder = num1 % num2;
        num1 = num2;
        num2 = remainder;
    }

    return abs(num1); // Return absolute value of GCD
}

int main() {
    // Example usage
    cout << gcd(18, 12) << endl; // Output: 6
    cout << gcd(0, 3) << endl; // Output: 3
    cout << gcd(17, 0) << endl; // Output: 17
    cout << gcd(0, 0) << endl; // Output: 0

    return 0;
}
```

The function starts by checking if both input values are zero, in which case it returns 0. It then checks if either input value is zero and returns the absolute value of the other input value if true. The `abs()` function ensures that any negative input values are converted into their positive counterparts.

Next, the function ensures that the first input value (`num1`) is greater than or equal to the second input value (`num2`) by swapping their values if necessary. This enables the remainder calculation in the while loop to always be positive.

The while loop uses the Euclidean algorithm to compute the GCD by repeatedly finding the remainder of the division of `num1` by `num2` and updating the values accordingly. The loop stops when `num2` is zero, and the GCD is returned as the absolute value of `num1`.

Finally, the function is used in the `main()` function to test the output values for various inputs. The `using namespace std;` declaration and `iostream` and `cmath` headers are included for input/output and absolute value functionalities.

